package unicodewidth

import (
	"unicode/utf8"

	"github.com/BrokkAi/mjolnir/go/rs"
)

// tablesWidthInfo is the crate's `WidthInfo(u16)`: what the character to the
// right of the one being measured asks of it.
type tablesWidthInfo uint16

const tablesLigatureTransparentMask uint16 = 0b0010_0000_0000_0000

const (
	// No special handling necessary
	tablesWidthInfoDefault                              tablesWidthInfo = 0
	tablesWidthInfoLineFeed                             tablesWidthInfo = 0b0000000000000001
	tablesWidthInfoEmojiModifier                        tablesWidthInfo = 0b0000000000000010
	tablesWidthInfoRegionalIndicator                    tablesWidthInfo = 0b0000000000000011
	tablesWidthInfoSeveralRegionalIndicator             tablesWidthInfo = 0b0000000000000100
	tablesWidthInfoEmojiPresentation                    tablesWidthInfo = 0b0000000000000101
	tablesWidthInfoZwjEmojiPresentation                 tablesWidthInfo = 0b0001000000000110
	tablesWidthInfoVs16ZwjEmojiPresentation             tablesWidthInfo = 0b1001000000000110
	tablesWidthInfoKeycapZwjEmojiPresentation           tablesWidthInfo = 0b0001000000000111
	tablesWidthInfoVs16KeycapZwjEmojiPresentation       tablesWidthInfo = 0b1001000000000111
	tablesWidthInfoRegionalIndicatorZwjPresentation     tablesWidthInfo = 0b0000000000001001
	tablesWidthInfoEvenRegionalIndicatorZwjPresentation tablesWidthInfo = 0b0000000000001010
	tablesWidthInfoOddRegionalIndicatorZwjPresentation  tablesWidthInfo = 0b0000000000001011
	tablesWidthInfoTagEndZwjEmojiPresentation           tablesWidthInfo = 0b0000000000010000
	tablesWidthInfoTagD1EndZwjEmojiPresentation         tablesWidthInfo = 0b0000000000010001
	tablesWidthInfoTagD2EndZwjEmojiPresentation         tablesWidthInfo = 0b0000000000010010
	tablesWidthInfoTagD3EndZwjEmojiPresentation         tablesWidthInfo = 0b0000000000010011
	tablesWidthInfoTagA1EndZwjEmojiPresentation         tablesWidthInfo = 0b0000000000011001
	tablesWidthInfoTagA2EndZwjEmojiPresentation         tablesWidthInfo = 0b0000000000011010
	tablesWidthInfoTagA3EndZwjEmojiPresentation         tablesWidthInfo = 0b0000000000011011
	tablesWidthInfoTagA4EndZwjEmojiPresentation         tablesWidthInfo = 0b0000000000011100
	tablesWidthInfoTagA5EndZwjEmojiPresentation         tablesWidthInfo = 0b0000000000011101
	tablesWidthInfoTagA6EndZwjEmojiPresentation         tablesWidthInfo = 0b0000000000011110
	tablesWidthInfoKiratRaiVowelSignE                   tablesWidthInfo = 0b0000000000100000
	tablesWidthInfoKiratRaiVowelSignAi                  tablesWidthInfo = 0b0000000000100001
	tablesWidthInfoVariationSelector12Or3               tablesWidthInfo = 0b0000001000000000
	tablesWidthInfoVariationSelector15                  tablesWidthInfo = 0b0100000000000000
	tablesWidthInfoVariationSelector16                  tablesWidthInfo = 0b1000000000000000
	tablesWidthInfoJoiningGroupAlef                     tablesWidthInfo = 0b0011000011111111
	// cfg(feature = "cjk")
	tablesWidthInfoCombiningLongSolidusOverlay tablesWidthInfo = 0b0011110011111111
	// cfg(feature = "cjk")
	tablesWidthInfoSolidusOverlayAlef            tablesWidthInfo = 0b0011100011111111
	tablesWidthInfoHebrewLetterLamed             tablesWidthInfo = 0b0011100000000000
	tablesWidthInfoZwjHebrewLetterLamed          tablesWidthInfo = 0b0011110000000000
	tablesWidthInfoBugineseLetterYa              tablesWidthInfo = 0b0011100000000001
	tablesWidthInfoZwjBugineseLetterYa           tablesWidthInfo = 0b0011110000000001
	tablesWidthInfoBugineseVowelSignIZwjLetterYa tablesWidthInfo = 0b0011110000000010
	tablesWidthInfoTifinaghConsonant             tablesWidthInfo = 0b0011100000000011
	tablesWidthInfoZwjTifinaghConsonant          tablesWidthInfo = 0b0011110000000011
	tablesWidthInfoTifinaghJoinerConsonant       tablesWidthInfo = 0b0011110000000100
	tablesWidthInfoLisuToneLetterMyaNaJeu        tablesWidthInfo = 0b0011110000000101
	tablesWidthInfoOldTurkicLetterOrkhonI        tablesWidthInfo = 0b0011100000000110
	tablesWidthInfoZwjOldTurkicLetterOrkhonI     tablesWidthInfo = 0b0011110000000110
	tablesWidthInfoKhmerCoengEligibleLetter      tablesWidthInfo = 0b0011110000000111
)

// Whether this width mode is ligature_transparent
// (has 5th MSB set.)
func (s tablesWidthInfo) isLigatureTransparent() bool {
	return (uint16(s) & 0b0000_1000_0000_0000) == 0b0000_1000_0000_0000
}

// Sets 6th MSB.
func (s tablesWidthInfo) setZwjBit() tablesWidthInfo {
	return tablesWidthInfo(uint16(s) | 0b0000_0100_0000_0000)
}

// Has top bit set
func (s tablesWidthInfo) isEmojiPresentation() bool {
	return (uint16(s) & uint16(tablesWidthInfoVariationSelector16)) == uint16(tablesWidthInfoVariationSelector16)
}

func (s tablesWidthInfo) isZwjEmojiPresentation() bool {
	return (uint16(s) & 0b1011_0000_0000_0000) == 0b1001_0000_0000_0000
}

// Set top bit
func (s tablesWidthInfo) setEmojiPresentation() tablesWidthInfo {
	if (uint16(s)&tablesLigatureTransparentMask) == tablesLigatureTransparentMask ||
		(uint16(s)&0b1001_0000_0000_0000) == 0b0001_0000_0000_0000 {
		// The grouping is Rust's: `&` binds tighter than `|`, so the other two
		// variation selector bits are cleared in the mask being added and stay
		// as they are in s.
		return tablesWidthInfo(
			uint16(s) |
				(uint16(tablesWidthInfoVariationSelector16) &
					^uint16(tablesWidthInfoVariationSelector15) &
					^uint16(tablesWidthInfoVariationSelector12Or3)),
		)
	} else {
		return tablesWidthInfoVariationSelector16
	}
}

// Clear top bit
func (s tablesWidthInfo) unsetEmojiPresentation() tablesWidthInfo {
	if (uint16(s) & tablesLigatureTransparentMask) == tablesLigatureTransparentMask {
		return tablesWidthInfo(uint16(s) & ^uint16(tablesWidthInfoVariationSelector16))
	} else {
		return tablesWidthInfoDefault
	}
}

// Has 2nd bit set
func (s tablesWidthInfo) isTextPresentation() bool {
	return (uint16(s) & uint16(tablesWidthInfoVariationSelector15)) == uint16(tablesWidthInfoVariationSelector15)
}

// Set 2nd bit
func (s tablesWidthInfo) setTextPresentation() tablesWidthInfo {
	if (uint16(s) & tablesLigatureTransparentMask) == tablesLigatureTransparentMask {
		return tablesWidthInfo(
			uint16(s) |
				(uint16(tablesWidthInfoVariationSelector15) &
					^uint16(tablesWidthInfoVariationSelector16) &
					^uint16(tablesWidthInfoVariationSelector12Or3)),
		)
	} else {
		return tablesWidthInfo(uint16(tablesWidthInfoVariationSelector15))
	}
}

// Clear 2nd bit
func (s tablesWidthInfo) unsetTextPresentation() tablesWidthInfo {
	return tablesWidthInfo(uint16(s) & ^uint16(tablesWidthInfoVariationSelector15))
}

// Has 7th bit set
func (s tablesWidthInfo) isVs123() bool {
	return (uint16(s) & uint16(tablesWidthInfoVariationSelector12Or3)) ==
		uint16(tablesWidthInfoVariationSelector12Or3)
}

// Set 7th bit
func (s tablesWidthInfo) setVs123() tablesWidthInfo {
	if (uint16(s) & tablesLigatureTransparentMask) == tablesLigatureTransparentMask {
		return tablesWidthInfo(
			uint16(s) |
				(uint16(tablesWidthInfoVariationSelector12Or3) &
					^uint16(tablesWidthInfoVariationSelector15) &
					^uint16(tablesWidthInfoVariationSelector16)),
		)
	} else {
		return tablesWidthInfo(uint16(tablesWidthInfoVariationSelector12Or3))
	}
}

// Clear 7th bit
func (s tablesWidthInfo) unsetVs123() tablesWidthInfo {
	return tablesWidthInfo(uint16(s) & ^uint16(tablesWidthInfoVariationSelector12Or3))
}

// UnicodeVersion is `unicode_width::UNICODE_VERSION`:
// the version of [Unicode](http://www.unicode.org/)
// that this version of unicode-width is based on.
var UnicodeVersion = rs.Tuple3[uint8, uint8, uint8]{F0: 17, F1: 0, F2: 0}

// Returns the [UAX #11](https://www.unicode.org/reports/tr11/) based width of `c` by
// consulting a multi-level lookup table.
//
// # Maintenance
// The tables themselves are autogenerated but this function is hardcoded. You should have
// nothing to worry about if you re-run `unicode.py` (for example, when updating Unicode.)
// However, if you change the *actual structure* of the lookup tables (perhaps by editing the
// `make_tables` function in `unicode.py`) you must ensure that this code reflects those changes.
func tablesLookupWidth(c rune) (uint8, tablesWidthInfo) {
	cp := int(c)

	t1Offset := tablesWidthRoot[cp>>13]

	// Each sub-table in WIDTH_MIDDLE is 7 bits, and each stored entry is a byte,
	// so each sub-table is 128 bytes in size.
	// (Sub-tables are selected using the computed offset from the previous table.)
	t2Offset := tablesWidthMiddle[int(t1Offset)][(cp>>7)&0x3F]

	// Each sub-table in WIDTH_LEAVES is 6 bits, but each stored entry is 2 bits.
	// This is accomplished by packing four stored entries into one byte.
	// So each sub-table is 2**(7-2) == 32 bytes in size.
	// Since this is the last table, each entry represents an encoded width.
	packedWidths := tablesWidthLeaves[int(t2Offset)][(cp>>2)&0x1F]

	// Extract the packed width
	width := (packedWidths >> (2 * (cp & 0b11))) & 0b11

	if width < 3 {
		return width, tablesWidthInfoDefault
	} else {
		switch {
		case c == 0xA:
			return 1, tablesWidthInfoLineFeed
		case c == 0x5DC:
			return 1, tablesWidthInfoHebrewLetterLamed
		case c >= 0x622 && c <= 0x882:
			return 1, tablesWidthInfoJoiningGroupAlef
		case c >= 0x1780 && c <= 0x17AF:
			return 1, tablesWidthInfoKhmerCoengEligibleLetter
		case c == 0x17D8:
			return 3, tablesWidthInfoDefault
		case c == 0x1A10:
			return 1, tablesWidthInfoBugineseLetterYa
		case c >= 0x2D31 && c <= 0x2D6F:
			return 1, tablesWidthInfoTifinaghConsonant
		case c >= 0xA4FC && c <= 0xA4FD:
			return 1, tablesWidthInfoLisuToneLetterMyaNaJeu
		case c == 0xFE01:
			return 0, tablesWidthInfoVariationSelector12Or3
		case c == 0xFE0E:
			return 0, tablesWidthInfoVariationSelector15
		case c == 0xFE0F:
			return 0, tablesWidthInfoVariationSelector16
		case c == 0x10C03:
			return 1, tablesWidthInfoOldTurkicLetterOrkhonI
		case c == 0x16D67:
			return 1, tablesWidthInfoKiratRaiVowelSignE
		case c == 0x16D68:
			return 1, tablesWidthInfoKiratRaiVowelSignAi
		case c >= 0x1F1E6 && c <= 0x1F1FF:
			return 1, tablesWidthInfoRegionalIndicator
		case c >= 0x1F3FB && c <= 0x1F3FF:
			return 2, tablesWidthInfoEmojiModifier
		default:
			return 2, tablesWidthInfoEmojiPresentation
		}
	}
}

// Returns the [UAX #11](https://www.unicode.org/reports/tr11/) based width of `c`, or
// `None` if `c` is a control character.
// Ambiguous width characters are treated as narrow.
func tablesSingleCharWidth(c rune) rs.Option[int] {
	if c < 0x7F {
		if c >= 0x20 {
			// U+0020 to U+007F (exclusive) are single-width ASCII codepoints
			return rs.Some(1)
		} else {
			// U+0000 to U+0020 (exclusive) are control codes
			return rs.None[int]()
		}
	} else if c >= 0xA0 {
		// No characters >= U+00A0 are control codes, so we can consult the lookup tables
		width, _ := tablesLookupWidth(c)
		return rs.Some(int(width))
	} else {
		// U+007F to U+00A0 (exclusive) are control codes
		return rs.None[int]()
	}
}

// Returns the [UAX #11](https://www.unicode.org/reports/tr11/) based width of `c`.
// Ambiguous width characters are treated as narrow.
func tablesWidthInStr(c rune, nextInfo tablesWidthInfo) (int8, tablesWidthInfo) {
	if nextInfo.isEmojiPresentation() {
		if tablesStartsEmojiPresentationSeq(c) {
			var width int8
			if nextInfo.isZwjEmojiPresentation() {
				width = 0
			} else {
				width = 2
			}
			return width, tablesWidthInfoEmojiPresentation
		} else {
			nextInfo = nextInfo.unsetEmojiPresentation()
		}
	}
	if c <= 0xA0 {
		switch {
		case c == '\n':
			return 1, tablesWidthInfoLineFeed
		case c == '\r' && nextInfo == tablesWidthInfoLineFeed:
			return 0, tablesWidthInfoDefault
		default:
			return 1, tablesWidthInfoDefault
		}
	} else {
		// Fast path
		if nextInfo != tablesWidthInfoDefault {
			if c == 0xFE0F {
				return 0, nextInfo.setEmojiPresentation()
			}
			if c == 0xFE01 {
				return 0, nextInfo.setVs123()
			}
			if c == 0xFE0E {
				return 0, nextInfo.setTextPresentation()
			}
			if nextInfo.isTextPresentation() {
				if tablesStartsNonIdeographicTextPresentationSeq(c) {
					return 1, tablesWidthInfoDefault
				} else {
					nextInfo = nextInfo.unsetTextPresentation()
				}
			} else if nextInfo.isVs123() {
				if c == 0x2018 || c == 0x2019 || c == 0x201C || c == 0x201D {
					return 2, tablesWidthInfoDefault
				} else {
					nextInfo = nextInfo.unsetVs123()
				}
			}
			if nextInfo.isLigatureTransparent() {
				if c == 0x200D {
					return 0, nextInfo.setZwjBit()
				} else if tablesIsLigatureTransparent(c) {
					return 0, nextInfo
				}
			}

			// A Rust `match (next_info, c)`: the first case that holds wins.
			switch {
			// Arabic Lam-Alef ligature
			case nextInfo == tablesWidthInfoJoiningGroupAlef &&
				(c == 0x644 || (c >= 0x6B5 && c <= 0x6B8) || c == 0x76A || c == 0x8A6 || c == 0x8C7):
				return 0, tablesWidthInfoDefault
			case nextInfo == tablesWidthInfoJoiningGroupAlef && tablesIsTransparentZeroWidth(c):
				return 0, tablesWidthInfoJoiningGroupAlef

			// Hebrew Alef-ZWJ-Lamed ligature
			case nextInfo == tablesWidthInfoZwjHebrewLetterLamed && c == 0x05D0:
				return 0, tablesWidthInfoDefault

			// Khmer coeng signs
			case nextInfo == tablesWidthInfoKhmerCoengEligibleLetter && c == 0x17D2:
				return -1, tablesWidthInfoDefault

			// Buginese <a, -i> ZWJ ya ligature
			case nextInfo == tablesWidthInfoZwjBugineseLetterYa && c == 0x1A17:
				return 0, tablesWidthInfoBugineseVowelSignIZwjLetterYa
			case nextInfo == tablesWidthInfoBugineseVowelSignIZwjLetterYa && c == 0x1A15:
				return 0, tablesWidthInfoDefault

			// Tifinagh bi-consonants
			case (nextInfo == tablesWidthInfoTifinaghConsonant || nextInfo == tablesWidthInfoZwjTifinaghConsonant) &&
				c == 0x2D7F:
				return 1, tablesWidthInfoTifinaghJoinerConsonant
			case nextInfo == tablesWidthInfoZwjTifinaghConsonant && ((c >= 0x2D31 && c <= 0x2D65) || c == 0x2D6F):
				return 0, tablesWidthInfoDefault
			case nextInfo == tablesWidthInfoTifinaghJoinerConsonant && ((c >= 0x2D31 && c <= 0x2D65) || c == 0x2D6F):
				return -1, tablesWidthInfoDefault

			// Lisu tone letter combinations
			case nextInfo == tablesWidthInfoLisuToneLetterMyaNaJeu && c >= 0xA4F8 && c <= 0xA4FB:
				return 0, tablesWidthInfoDefault

			// Old Turkic ligature
			case nextInfo == tablesWidthInfoZwjOldTurkicLetterOrkhonI && c == 0x10C32:
				return 0, tablesWidthInfoDefault
			// Emoji modifier
			case nextInfo == tablesWidthInfoEmojiModifier && tablesIsEmojiModifierBase(c):
				return 0, tablesWidthInfoEmojiPresentation

			// Regional indicator
			case (nextInfo == tablesWidthInfoRegionalIndicator || nextInfo == tablesWidthInfoSeveralRegionalIndicator) &&
				c >= 0x1F1E6 && c <= 0x1F1FF:
				return 1, tablesWidthInfoSeveralRegionalIndicator

			// ZWJ emoji
			case (nextInfo == tablesWidthInfoEmojiPresentation ||
				nextInfo == tablesWidthInfoSeveralRegionalIndicator ||
				nextInfo == tablesWidthInfoEvenRegionalIndicatorZwjPresentation ||
				nextInfo == tablesWidthInfoOddRegionalIndicatorZwjPresentation ||
				nextInfo == tablesWidthInfoEmojiModifier) &&
				c == 0x200D:
				return 0, tablesWidthInfoZwjEmojiPresentation
			case nextInfo == tablesWidthInfoZwjEmojiPresentation && c == 0x20E3:
				return 0, tablesWidthInfoKeycapZwjEmojiPresentation
			case nextInfo == tablesWidthInfoVs16ZwjEmojiPresentation && tablesStartsEmojiPresentationSeq(c):
				return 0, tablesWidthInfoEmojiPresentation
			case nextInfo == tablesWidthInfoVs16KeycapZwjEmojiPresentation &&
				((c >= '0' && c <= '9') || c == '#' || c == '*'):
				return 0, tablesWidthInfoEmojiPresentation
			case nextInfo == tablesWidthInfoZwjEmojiPresentation && c >= 0x1F1E6 && c <= 0x1F1FF:
				return 1, tablesWidthInfoRegionalIndicatorZwjPresentation
			case (nextInfo == tablesWidthInfoRegionalIndicatorZwjPresentation ||
				nextInfo == tablesWidthInfoOddRegionalIndicatorZwjPresentation) &&
				c >= 0x1F1E6 && c <= 0x1F1FF:
				return -1, tablesWidthInfoEvenRegionalIndicatorZwjPresentation
			case nextInfo == tablesWidthInfoEvenRegionalIndicatorZwjPresentation && c >= 0x1F1E6 && c <= 0x1F1FF:
				return 3, tablesWidthInfoOddRegionalIndicatorZwjPresentation
			case nextInfo == tablesWidthInfoZwjEmojiPresentation && c >= 0x1F3FB && c <= 0x1F3FF:
				return 0, tablesWidthInfoEmojiModifier
			case nextInfo == tablesWidthInfoZwjEmojiPresentation && c == 0xE007F:
				return 0, tablesWidthInfoTagEndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagEndZwjEmojiPresentation && c >= 0xE0061 && c <= 0xE007A:
				return 0, tablesWidthInfoTagA1EndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagA1EndZwjEmojiPresentation && c >= 0xE0061 && c <= 0xE007A:
				return 0, tablesWidthInfoTagA2EndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagA2EndZwjEmojiPresentation && c >= 0xE0061 && c <= 0xE007A:
				return 0, tablesWidthInfoTagA3EndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagA3EndZwjEmojiPresentation && c >= 0xE0061 && c <= 0xE007A:
				return 0, tablesWidthInfoTagA4EndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagA4EndZwjEmojiPresentation && c >= 0xE0061 && c <= 0xE007A:
				return 0, tablesWidthInfoTagA5EndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagA5EndZwjEmojiPresentation && c >= 0xE0061 && c <= 0xE007A:
				return 0, tablesWidthInfoTagA6EndZwjEmojiPresentation
			case (nextInfo == tablesWidthInfoTagEndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagA1EndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagA2EndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagA3EndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagA4EndZwjEmojiPresentation) &&
				c >= 0xE0030 && c <= 0xE0039:
				return 0, tablesWidthInfoTagD1EndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagD1EndZwjEmojiPresentation && c >= 0xE0030 && c <= 0xE0039:
				return 0, tablesWidthInfoTagD2EndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagD2EndZwjEmojiPresentation && c >= 0xE0030 && c <= 0xE0039:
				return 0, tablesWidthInfoTagD3EndZwjEmojiPresentation
			case (nextInfo == tablesWidthInfoTagA3EndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagA4EndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagA5EndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagA6EndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagD3EndZwjEmojiPresentation) &&
				c == 0x1F3F4:
				return 0, tablesWidthInfoEmojiPresentation
			case nextInfo == tablesWidthInfoZwjEmojiPresentation && tablesLookupWidthInfo(c) == tablesWidthInfoEmojiPresentation:
				return 0, tablesWidthInfoEmojiPresentation

			case nextInfo == tablesWidthInfoKiratRaiVowelSignE && c == 0x16D63:
				return 0, tablesWidthInfoDefault
			case nextInfo == tablesWidthInfoKiratRaiVowelSignE && c == 0x16D67:
				return 0, tablesWidthInfoKiratRaiVowelSignAi
			case nextInfo == tablesWidthInfoKiratRaiVowelSignE && c == 0x16D68:
				return 1, tablesWidthInfoKiratRaiVowelSignE
			case nextInfo == tablesWidthInfoKiratRaiVowelSignE && c == 0x16D69:
				return 0, tablesWidthInfoDefault
			case nextInfo == tablesWidthInfoKiratRaiVowelSignAi && c == 0x16D63:
				return 0, tablesWidthInfoDefault

			// Fallback
			default:
			}
		}

		width, info := tablesLookupWidth(c)
		return int8(width), info
	}
}

// tablesLookupWidthInfo is `lookup_width(c).1`, which Go cannot write inside
// an expression.
func tablesLookupWidthInfo(c rune) tablesWidthInfo {
	_, info := tablesLookupWidth(c)
	return info
}

func tablesStrWidth(s string) int {
	// A Rust `s.chars().rfold(..)`: the characters are visited from the last
	// to the first, each one told what the character to its right asked for.
	var sum uint
	nextInfo := tablesWidthInfoDefault
	for end := len(s); end > 0; {
		c, size := utf8.DecodeLastRuneInString(s[:end])
		end -= size
		add, info := tablesWidthInStr(c, nextInfo)
		// sum.wrapping_add_signed(isize::from(add))
		sum += uint(int(add))
		nextInfo = info
	}
	return int(sum)
}

// Returns the [UAX #11](https://www.unicode.org/reports/tr11/) based width of `c` by
// consulting a multi-level lookup table.
//
// # Maintenance
// The tables themselves are autogenerated but this function is hardcoded. You should have
// nothing to worry about if you re-run `unicode.py` (for example, when updating Unicode.)
// However, if you change the *actual structure* of the lookup tables (perhaps by editing the
// `make_tables` function in `unicode.py`) you must ensure that this code reflects those changes.
//
// cfg(feature = "cjk")
func tablesLookupWidthCjk(c rune) (uint8, tablesWidthInfo) {
	cp := int(c)

	t1Offset := tablesWidthRootCjk[cp>>13]

	// Each sub-table in WIDTH_MIDDLE is 7 bits, and each stored entry is a byte,
	// so each sub-table is 128 bytes in size.
	// (Sub-tables are selected using the computed offset from the previous table.)
	t2Offset := tablesWidthMiddle[int(t1Offset)][(cp>>7)&0x3F]

	// Each sub-table in WIDTH_LEAVES is 6 bits, but each stored entry is 2 bits.
	// This is accomplished by packing four stored entries into one byte.
	// So each sub-table is 2**(7-2) == 32 bytes in size.
	// Since this is the last table, each entry represents an encoded width.
	packedWidths := tablesWidthLeaves[int(t2Offset)][(cp>>2)&0x1F]

	// Extract the packed width
	width := (packedWidths >> (2 * (cp & 0b11))) & 0b11

	if width < 3 {
		return width, tablesWidthInfoDefault
	} else {
		switch {
		case c == 0xA:
			return 1, tablesWidthInfoLineFeed
		case c == 0x338:
			return 0, tablesWidthInfoCombiningLongSolidusOverlay
		case c == 0x5DC:
			return 1, tablesWidthInfoHebrewLetterLamed
		case c >= 0x622 && c <= 0x882:
			return 1, tablesWidthInfoJoiningGroupAlef
		case c >= 0x1780 && c <= 0x17AF:
			return 1, tablesWidthInfoKhmerCoengEligibleLetter
		case c == 0x17D8:
			return 3, tablesWidthInfoDefault
		case c == 0x1A10:
			return 1, tablesWidthInfoBugineseLetterYa
		case c >= 0x2D31 && c <= 0x2D6F:
			return 1, tablesWidthInfoTifinaghConsonant
		case c >= 0xA4FC && c <= 0xA4FD:
			return 1, tablesWidthInfoLisuToneLetterMyaNaJeu
		case c >= 0xFE00 && c <= 0xFE02:
			return 0, tablesWidthInfoVariationSelector12Or3
		case c == 0xFE0F:
			return 0, tablesWidthInfoVariationSelector16
		case c == 0x10C03:
			return 1, tablesWidthInfoOldTurkicLetterOrkhonI
		case c == 0x16D67:
			return 1, tablesWidthInfoKiratRaiVowelSignE
		case c == 0x16D68:
			return 1, tablesWidthInfoKiratRaiVowelSignAi
		case c >= 0x1F1E6 && c <= 0x1F1FF:
			return 1, tablesWidthInfoRegionalIndicator
		case c >= 0x1F3FB && c <= 0x1F3FF:
			return 2, tablesWidthInfoEmojiModifier
		default:
			return 2, tablesWidthInfoEmojiPresentation
		}
	}
}

// Returns the [UAX #11](https://www.unicode.org/reports/tr11/) based width of `c`, or
// `None` if `c` is a control character.
// Ambiguous width characters are treated as wide.
//
// cfg(feature = "cjk")
func tablesSingleCharWidthCjk(c rune) rs.Option[int] {
	if c < 0x7F {
		if c >= 0x20 {
			// U+0020 to U+007F (exclusive) are single-width ASCII codepoints
			return rs.Some(1)
		} else {
			// U+0000 to U+0020 (exclusive) are control codes
			return rs.None[int]()
		}
	} else if c >= 0xA0 {
		// No characters >= U+00A0 are control codes, so we can consult the lookup tables
		width, _ := tablesLookupWidthCjk(c)
		return rs.Some(int(width))
	} else {
		// U+007F to U+00A0 (exclusive) are control codes
		return rs.None[int]()
	}
}

// Returns the [UAX #11](https://www.unicode.org/reports/tr11/) based width of `c`.
// Ambiguous width characters are treated as wide.
//
// cfg(feature = "cjk")
func tablesWidthInStrCjk(c rune, nextInfo tablesWidthInfo) (int8, tablesWidthInfo) {
	if nextInfo.isEmojiPresentation() {
		if tablesStartsEmojiPresentationSeq(c) {
			var width int8
			if nextInfo.isZwjEmojiPresentation() {
				width = 0
			} else {
				width = 2
			}
			return width, tablesWidthInfoEmojiPresentation
		} else {
			nextInfo = nextInfo.unsetEmojiPresentation()
		}
	}
	if (nextInfo == tablesWidthInfoCombiningLongSolidusOverlay || nextInfo == tablesWidthInfoSolidusOverlayAlef) &&
		(c == '<' || c == '=' || c == '>') {
		return 2, tablesWidthInfoDefault
	}
	if c <= 0xA0 {
		switch {
		case c == '\n':
			return 1, tablesWidthInfoLineFeed
		case c == '\r' && nextInfo == tablesWidthInfoLineFeed:
			return 0, tablesWidthInfoDefault
		default:
			return 1, tablesWidthInfoDefault
		}
	} else {
		// Fast path
		if nextInfo != tablesWidthInfoDefault {
			if c == 0xFE0F {
				return 0, nextInfo.setEmojiPresentation()
			}
			if c == 0xFE00 || c == 0xFE02 {
				return 0, nextInfo.setVs123()
			}
			if nextInfo.isVs123() {
				if c == 0x2018 || c == 0x2019 || c == 0x201C || c == 0x201D {
					return 1, tablesWidthInfoDefault
				} else {
					nextInfo = nextInfo.unsetVs123()
				}
			}
			if nextInfo.isLigatureTransparent() {
				if c == 0x200D {
					return 0, nextInfo.setZwjBit()
				} else if tablesIsLigatureTransparent(c) {
					return 0, nextInfo
				}
			}

			// A Rust `match (next_info, c)`: the first case that holds wins.
			switch {
			case nextInfo == tablesWidthInfoCombiningLongSolidusOverlay && tablesIsSolidusTransparent(c):
				width, _ := tablesLookupWidthCjk(c)
				return int8(width), tablesWidthInfoCombiningLongSolidusOverlay
			case nextInfo == tablesWidthInfoJoiningGroupAlef && c == 0x0338:
				return 0, tablesWidthInfoSolidusOverlayAlef
			// Arabic Lam-Alef ligature
			case (nextInfo == tablesWidthInfoJoiningGroupAlef || nextInfo == tablesWidthInfoSolidusOverlayAlef) &&
				(c == 0x644 || (c >= 0x6B5 && c <= 0x6B8) || c == 0x76A || c == 0x8A6 || c == 0x8C7):
				return 0, tablesWidthInfoDefault
			case nextInfo == tablesWidthInfoJoiningGroupAlef && tablesIsTransparentZeroWidth(c):
				return 0, tablesWidthInfoJoiningGroupAlef

			// Hebrew Alef-ZWJ-Lamed ligature
			case nextInfo == tablesWidthInfoZwjHebrewLetterLamed && c == 0x05D0:
				return 0, tablesWidthInfoDefault

			// Khmer coeng signs
			case nextInfo == tablesWidthInfoKhmerCoengEligibleLetter && c == 0x17D2:
				return -1, tablesWidthInfoDefault

			// Buginese <a, -i> ZWJ ya ligature
			case nextInfo == tablesWidthInfoZwjBugineseLetterYa && c == 0x1A17:
				return 0, tablesWidthInfoBugineseVowelSignIZwjLetterYa
			case nextInfo == tablesWidthInfoBugineseVowelSignIZwjLetterYa && c == 0x1A15:
				return 0, tablesWidthInfoDefault

			// Tifinagh bi-consonants
			case (nextInfo == tablesWidthInfoTifinaghConsonant || nextInfo == tablesWidthInfoZwjTifinaghConsonant) &&
				c == 0x2D7F:
				return 1, tablesWidthInfoTifinaghJoinerConsonant
			case nextInfo == tablesWidthInfoZwjTifinaghConsonant && ((c >= 0x2D31 && c <= 0x2D65) || c == 0x2D6F):
				return 0, tablesWidthInfoDefault
			case nextInfo == tablesWidthInfoTifinaghJoinerConsonant && ((c >= 0x2D31 && c <= 0x2D65) || c == 0x2D6F):
				return -1, tablesWidthInfoDefault

			// Lisu tone letter combinations
			case nextInfo == tablesWidthInfoLisuToneLetterMyaNaJeu && c >= 0xA4F8 && c <= 0xA4FB:
				return 0, tablesWidthInfoDefault

			// Old Turkic ligature
			case nextInfo == tablesWidthInfoZwjOldTurkicLetterOrkhonI && c == 0x10C32:
				return 0, tablesWidthInfoDefault
			// Emoji modifier
			case nextInfo == tablesWidthInfoEmojiModifier && tablesIsEmojiModifierBase(c):
				return 0, tablesWidthInfoEmojiPresentation

			// Regional indicator
			case (nextInfo == tablesWidthInfoRegionalIndicator || nextInfo == tablesWidthInfoSeveralRegionalIndicator) &&
				c >= 0x1F1E6 && c <= 0x1F1FF:
				return 1, tablesWidthInfoSeveralRegionalIndicator

			// ZWJ emoji
			case (nextInfo == tablesWidthInfoEmojiPresentation ||
				nextInfo == tablesWidthInfoSeveralRegionalIndicator ||
				nextInfo == tablesWidthInfoEvenRegionalIndicatorZwjPresentation ||
				nextInfo == tablesWidthInfoOddRegionalIndicatorZwjPresentation ||
				nextInfo == tablesWidthInfoEmojiModifier) &&
				c == 0x200D:
				return 0, tablesWidthInfoZwjEmojiPresentation
			case nextInfo == tablesWidthInfoZwjEmojiPresentation && c == 0x20E3:
				return 0, tablesWidthInfoKeycapZwjEmojiPresentation
			case nextInfo == tablesWidthInfoVs16ZwjEmojiPresentation && tablesStartsEmojiPresentationSeq(c):
				return 0, tablesWidthInfoEmojiPresentation
			case nextInfo == tablesWidthInfoVs16KeycapZwjEmojiPresentation &&
				((c >= '0' && c <= '9') || c == '#' || c == '*'):
				return 0, tablesWidthInfoEmojiPresentation
			case nextInfo == tablesWidthInfoZwjEmojiPresentation && c >= 0x1F1E6 && c <= 0x1F1FF:
				return 1, tablesWidthInfoRegionalIndicatorZwjPresentation
			case (nextInfo == tablesWidthInfoRegionalIndicatorZwjPresentation ||
				nextInfo == tablesWidthInfoOddRegionalIndicatorZwjPresentation) &&
				c >= 0x1F1E6 && c <= 0x1F1FF:
				return -1, tablesWidthInfoEvenRegionalIndicatorZwjPresentation
			case nextInfo == tablesWidthInfoEvenRegionalIndicatorZwjPresentation && c >= 0x1F1E6 && c <= 0x1F1FF:
				return 3, tablesWidthInfoOddRegionalIndicatorZwjPresentation
			case nextInfo == tablesWidthInfoZwjEmojiPresentation && c >= 0x1F3FB && c <= 0x1F3FF:
				return 0, tablesWidthInfoEmojiModifier
			case nextInfo == tablesWidthInfoZwjEmojiPresentation && c == 0xE007F:
				return 0, tablesWidthInfoTagEndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagEndZwjEmojiPresentation && c >= 0xE0061 && c <= 0xE007A:
				return 0, tablesWidthInfoTagA1EndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagA1EndZwjEmojiPresentation && c >= 0xE0061 && c <= 0xE007A:
				return 0, tablesWidthInfoTagA2EndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagA2EndZwjEmojiPresentation && c >= 0xE0061 && c <= 0xE007A:
				return 0, tablesWidthInfoTagA3EndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagA3EndZwjEmojiPresentation && c >= 0xE0061 && c <= 0xE007A:
				return 0, tablesWidthInfoTagA4EndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagA4EndZwjEmojiPresentation && c >= 0xE0061 && c <= 0xE007A:
				return 0, tablesWidthInfoTagA5EndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagA5EndZwjEmojiPresentation && c >= 0xE0061 && c <= 0xE007A:
				return 0, tablesWidthInfoTagA6EndZwjEmojiPresentation
			case (nextInfo == tablesWidthInfoTagEndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagA1EndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagA2EndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagA3EndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagA4EndZwjEmojiPresentation) &&
				c >= 0xE0030 && c <= 0xE0039:
				return 0, tablesWidthInfoTagD1EndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagD1EndZwjEmojiPresentation && c >= 0xE0030 && c <= 0xE0039:
				return 0, tablesWidthInfoTagD2EndZwjEmojiPresentation
			case nextInfo == tablesWidthInfoTagD2EndZwjEmojiPresentation && c >= 0xE0030 && c <= 0xE0039:
				return 0, tablesWidthInfoTagD3EndZwjEmojiPresentation
			case (nextInfo == tablesWidthInfoTagA3EndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagA4EndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagA5EndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagA6EndZwjEmojiPresentation ||
				nextInfo == tablesWidthInfoTagD3EndZwjEmojiPresentation) &&
				c == 0x1F3F4:
				return 0, tablesWidthInfoEmojiPresentation
			case nextInfo == tablesWidthInfoZwjEmojiPresentation && tablesLookupWidthCjkInfo(c) == tablesWidthInfoEmojiPresentation:
				return 0, tablesWidthInfoEmojiPresentation

			case nextInfo == tablesWidthInfoKiratRaiVowelSignE && c == 0x16D63:
				return 0, tablesWidthInfoDefault
			case nextInfo == tablesWidthInfoKiratRaiVowelSignE && c == 0x16D67:
				return 0, tablesWidthInfoKiratRaiVowelSignAi
			case nextInfo == tablesWidthInfoKiratRaiVowelSignE && c == 0x16D68:
				return 1, tablesWidthInfoKiratRaiVowelSignE
			case nextInfo == tablesWidthInfoKiratRaiVowelSignE && c == 0x16D69:
				return 0, tablesWidthInfoDefault
			case nextInfo == tablesWidthInfoKiratRaiVowelSignAi && c == 0x16D63:
				return 0, tablesWidthInfoDefault

			// Fallback
			default:
			}
		}

		width, info := tablesLookupWidthCjk(c)
		return int8(width), info
	}
}

// tablesLookupWidthCjkInfo is `lookup_width_cjk(c).1`, which Go cannot write
// inside an expression.
func tablesLookupWidthCjkInfo(c rune) tablesWidthInfo {
	_, info := tablesLookupWidthCjk(c)
	return info
}

// cfg(feature = "cjk")
func tablesStrWidthCjk(s string) int {
	// A Rust `s.chars().rfold(..)`, as in tablesStrWidth.
	var sum uint
	nextInfo := tablesWidthInfoDefault
	for end := len(s); end > 0; {
		c, size := utf8.DecodeLastRuneInString(s[:end])
		end -= size
		add, info := tablesWidthInStrCjk(c, nextInfo)
		// sum.wrapping_add_signed(isize::from(add))
		sum += uint(int(add))
		nextInfo = info
	}
	return int(sum)
}

// Whether this character is a zero-width character with
// `Joining_Type=Transparent`. Used by the Alef-Lamed ligatures.
// See also [`is_ligature_transparent`], a near-subset of this (only ZWJ is excepted)
// which is transparent for non-Arabic ligatures.
func tablesIsTransparentZeroWidth(c rune) bool {
	if width, _ := tablesLookupWidth(c); width != 0 {
		// Not zero-width
		return false
	} else {
		cp := uint32(c)
		_, found := sliceBinarySearchBy(tablesNonTransparentZeroWidths[:], func(entry *rs.Tuple2[[3]uint8, [3]uint8]) int {
			lo := u32FromLeBytes(entry.F0[0], entry.F0[1], entry.F0[2], 0)
			hi := u32FromLeBytes(entry.F1[0], entry.F1[1], entry.F1[2], 0)
			if cp < lo {
				return orderingGreater
			} else if cp > hi {
				return orderingLess
			} else {
				return orderingEqual
			}
		})
		return !found
	}
}

// Whether this character is a default-ignorable combining mark
// or ZWJ. These characters won't interrupt non-Arabic ligatures.
func tablesIsLigatureTransparent(c rune) bool {
	return c == 0x34F || (c >= 0x17B4 && c <= 0x17B5) || (c >= 0x180B && c <= 0x180D) || c == 0x180F ||
		c == 0x200D || (c >= 0xFE00 && c <= 0xFE0F) || (c >= 0xE0100 && c <= 0xE01EF)
}

// Whether this character is transparent wrt the effect of
// U+0338 COMBINING LONG SOLIDUS OVERLAY
// on its base character.
//
// cfg(feature = "cjk")
func tablesIsSolidusTransparent(c rune) bool {
	cp := uint32(c)
	if tablesIsLigatureTransparent(c) {
		return true
	}
	_, found := sliceBinarySearchBy(tablesSolidusTransparent[:], func(entry *rs.Tuple2[[3]uint8, [3]uint8]) int {
		lo := u32FromLeBytes(entry.F0[0], entry.F0[1], entry.F0[2], 0)
		hi := u32FromLeBytes(entry.F1[0], entry.F1[1], entry.F1[2], 0)
		if cp < lo {
			return orderingGreater
		} else if cp > hi {
			return orderingLess
		} else {
			return orderingEqual
		}
	})
	return found
}

// Whether this character forms an [emoji presentation sequence]
// (https://www.unicode.org/reports/tr51/#def_emoji_presentation_sequence)
// when followed by `'\u{FEOF}'`.
// Emoji presentation sequences are considered to have width 2.
func tablesStartsEmojiPresentationSeq(c rune) bool {
	cp := uint32(c)
	// First level of lookup uses all but 10 LSB
	topBits := cp >> 10
	var idxOfLeaf int
	switch topBits {
	case 0x0:
		idxOfLeaf = 0
	case 0x8:
		idxOfLeaf = 1
	case 0x9:
		idxOfLeaf = 2
	case 0xA:
		idxOfLeaf = 3
	case 0xC:
		idxOfLeaf = 4
	case 0x7C:
		idxOfLeaf = 5
	case 0x7D:
		idxOfLeaf = 6
	default:
		return false
	}
	// Extract the 3-9th (0-indexed) least significant bits of `cp`,
	// and use them to index into `leaf_row`.
	idxWithinLeaf := int((cp >> 3) & 0x7F)
	leafByte := tablesEmojiPresentationLeaves[idxOfLeaf][idxWithinLeaf]
	// Use the 3 LSB of `cp` to index into `leaf_byte`.
	return ((leafByte >> (cp & 7)) & 1) == 1
}

// Returns `true` if `c` has default emoji presentation, but forms a [text presentation sequence]
// (https://www.unicode.org/reports/tr51/#def_text_presentation_sequence)
// when followed by `'\u{FEOE}'`, and is not ideographic.
// Such sequences are considered to have width 1.
func tablesStartsNonIdeographicTextPresentationSeq(c rune) bool {
	cp := uint32(c)
	// First level of lookup uses all but 8 LSB
	topBits := cp >> 8
	var leaf []rs.Tuple2[uint8, uint8]
	switch topBits {
	case 0x23:
		leaf = tablesTextPresentationLeaf0[:]
	case 0x25:
		leaf = tablesTextPresentationLeaf1[:]
	case 0x26:
		leaf = tablesTextPresentationLeaf2[:]
	case 0x27:
		leaf = tablesTextPresentationLeaf3[:]
	case 0x2B:
		leaf = tablesTextPresentationLeaf4[:]
	case 0x1F0:
		leaf = tablesTextPresentationLeaf5[:]
	case 0x1F3:
		leaf = tablesTextPresentationLeaf6[:]
	case 0x1F4:
		leaf = tablesTextPresentationLeaf7[:]
	case 0x1F5:
		leaf = tablesTextPresentationLeaf8[:]
	case 0x1F6:
		leaf = tablesTextPresentationLeaf9[:]
	default:
		return false
	}

	bottomBits := uint8(cp & 0xFF)
	_, found := sliceBinarySearchBy(leaf, func(entry *rs.Tuple2[uint8, uint8]) int {
		lo, hi := entry.F0, entry.F1
		if bottomBits < lo {
			return orderingGreater
		} else if bottomBits > hi {
			return orderingLess
		} else {
			return orderingEqual
		}
	})
	return found
}

// Returns `true` if `c` is an `Emoji_Modifier_Base`.
func tablesIsEmojiModifierBase(c rune) bool {
	cp := uint32(c)
	// First level of lookup uses all but 8 LSB
	topBits := cp >> 8
	var leaf []rs.Tuple2[uint8, uint8]
	switch topBits {
	case 0x26:
		leaf = tablesEmojiModifierLeaf0[:]
	case 0x27:
		leaf = tablesEmojiModifierLeaf1[:]
	case 0x1F3:
		leaf = tablesEmojiModifierLeaf2[:]
	case 0x1F4:
		leaf = tablesEmojiModifierLeaf3[:]
	case 0x1F5:
		leaf = tablesEmojiModifierLeaf4[:]
	case 0x1F6:
		leaf = tablesEmojiModifierLeaf5[:]
	case 0x1F9:
		leaf = tablesEmojiModifierLeaf6[:]
	case 0x1FA:
		leaf = tablesEmojiModifierLeaf7[:]
	default:
		return false
	}

	bottomBits := uint8(cp & 0xFF)
	_, found := sliceBinarySearchBy(leaf, func(entry *rs.Tuple2[uint8, uint8]) int {
		lo, hi := entry.F0, entry.F1
		if bottomBits < lo {
			return orderingGreater
		} else if bottomBits > hi {
			return orderingLess
		} else {
			return orderingEqual
		}
	})
	return found
}

// The crate's `Align32`, `Align64` and `Align128` wrappers only fix the
// alignment of the tables in the Rust binary and have no Go counterpart. The
// tables follow in tables_data.go.

// The results of a comparison function given to sliceBinarySearchBy:
// `core::cmp::Ordering`.
const (
	orderingLess    = -1
	orderingEqual   = 0
	orderingGreater = 1
)

// sliceBinarySearchBy is `<[T]>::binary_search_by` of Rust 1.99.1
// (core/src/slice/mod.rs): the index of an element for which f returns
// orderingEqual and true, or the index where one would be inserted and false.
func sliceBinarySearchBy[T any](slice []T, f func(*T) int) (int, bool) {
	size := len(slice)
	if size == 0 {
		return 0, false
	}
	base := 0

	// This loop intentionally doesn't have an early exit if the comparison
	// returns Equal. We want the number of loop iterations to depend *only*
	// on the size of the input slice so that the CPU can reliably predict
	// the loop count.
	for size > 1 {
		half := size / 2
		mid := base + half

		cmp := f(&slice[mid])
		if cmp != orderingGreater {
			base = mid
		}

		// This is imprecise in the case where `size` is odd and the
		// comparison returns Greater: the mid element still gets included
		// by `size` even though it's known to be larger than the element
		// being searched for.
		//
		// This is fine though: we gain more performance by keeping the
		// loop iteration count invariant (and thus predictable) than we
		// lose from considering one additional element.
		size -= half
	}

	cmp := f(&slice[base])
	if cmp == orderingEqual {
		return base, true
	}
	if cmp == orderingLess {
		return base + 1, false
	}
	return base, false
}

// u32FromLeBytes is `u32::from_le_bytes`.
func u32FromLeBytes(b0, b1, b2, b3 uint8) uint32 {
	return uint32(b0) | uint32(b1)<<8 | uint32(b2)<<16 | uint32(b3)<<24
}
